using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Swashbuckle.AspNetCore.Annotations;using GraphApi.Models.USR.Parentescos;using GraphApi.Services.USR.Parentescos;namespace GraphApi.Controllers.USR.Parentescos{    /// <summary>    /// Gestión de Parentescos: consulta, creación, actualización y borrado.    /// </summary>    [ApiController]    [Authorize]    [Route("USR/[controller]")]    [Produces("application/json")]    [SwaggerTag("Operaciones sobre Parentescos")]    public class ParentescosController : Controller    {        private readonly IParentescosService _objService;        public ParentescosController(IParentescosService objService)        {            _objService = objService;        }        /// <summary>        /// Obtiene todos los Parentescos, con filtros opcionales.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="parentescoID">ParentescoID</param>        /// <param name="parentesco">Parentesco</param>        /// <param name="bEliminado">bEliminado</param>        /// <returns>Listado de Parentescos</returns>        [HttpGet]        [SwaggerOperation(            Summary = "Listar Parentescos",            Description = "Devuelve Parentescos aplicando filtros opcionales."        )]        [ProducesResponseType(typeof(IEnumerable<clReadParentescos>), StatusCodes.Status200OK)]        public async Task<ActionResult<IEnumerable<clReadParentescos>>> GetAll(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromQuery] int? parentescoID,            [FromQuery] string? parentesco,            [FromQuery] bool? bEliminado,            [FromQuery] string? columnNames)        {            var vList = await _objService.GetParentescosDynamic(                parentescoID,                 parentesco,                 bEliminado,                 columnNames, nUserId, sWindowName);              return vList.Count()==0  ? NotFound() :  Ok(vList);        }        /// <summary>        /// Crea un nuevo Parentesco.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Datos del Parentesco a crear.</param>        /// <returns>El Parentesco recién creado.</returns>        [HttpPost]        [SwaggerOperation(            Summary = "Crear Parentescos",            Description = "Inserta un nuevo Parentesco en la base de datos."        )]        [ProducesResponseType(typeof(clReadParentescos), StatusCodes.Status201Created)]        public async Task<ActionResult<clReadParentescos>> Create(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clCreateParentescos objInput)        {            var vCreated = await _objService.CreateParentescos(objInput, nUserId, sWindowName);            return vCreated is null ? NoContent() : vCreated;        }        /// <summary>        /// Actualización parcial de Parentesco.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Campos a actualizar y el ID del Parentesco.</param>        /// <returns>El Parentesco actualizado.</returns>        [HttpPatch]        [SwaggerOperation(            Summary = "Actualizar Parentescos",            Description = "Actualiza uno o varios campos de Parentesco existente."        )]        [ProducesResponseType(typeof(clReadParentescos), StatusCodes.Status200OK)]        public async Task<ActionResult<clReadParentescos>> Patch(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clUpdateParentescos objInput)        {            var vUpdated = await _objService.UpdateParentescos(objInput, nUserId, sWindowName);            return vUpdated is null ? NotFound() : Ok(vUpdated);        }        /// <summary>        /// Elimina un Parentesco por su ID.        /// </summary>        [HttpDelete("{nParentescosID:int}")]        [SwaggerOperation(            Summary = "Eliminar Parentesco",            Description = "Borra un Parentesco si existe."        )]        [ProducesResponseType(StatusCodes.Status204NoContent)]        public async Task<IActionResult> Delete(int nParentescosID)        {            var success = await _objService.DeleteParentescos(nParentescosID);            return success ? NoContent() : NotFound();        }    }}